import { z, createLogger, createPlugin, loadEnv, type ToolDefinition } from "openpets-sdk"
import { ElevenLabsClient, play } from "elevenlabs"
import { promises as fs } from "fs"
import * as fsSync from "fs"
import path from "path"
import { Readable } from "stream"
import { createVoiceCloningTools } from "./src/tools/voice-cloning"
import { createConversationTools } from "./src/tools/conversation"
import { createAudioTagsHelperTool } from "./src/tools/audio-tags-helper"
import { createScriptProductionTool } from "./src/tools/script-production"
import openAPITools from "./openapi-tools"
import { fetchAPI, getBaseUrl } from "./openapi-client"

// Voice samples directory for voice cloning
const VOICE_SAMPLES_DIR = path.join(__dirname, "voice-samples")

/**
 * Check if voice samples directory exists and contains audio files
 */
function getVoiceSamplesInfo(): { exists: boolean; files: string[]; totalDuration: string } {
  try {
    if (!fsSync.existsSync(VOICE_SAMPLES_DIR)) {
      return { exists: false, files: [], totalDuration: "0s" }
    }

    const files = fsSync.readdirSync(VOICE_SAMPLES_DIR)
      .filter(f => /\.(mp3|wav|m4a|ogg|flac)$/i.test(f))
      .map(f => path.join(VOICE_SAMPLES_DIR, f))

    return { 
      exists: files.length > 0, 
      files,
      totalDuration: `${files.length} file(s) found`
    }
  } catch {
    return { exists: false, files: [], totalDuration: "0s" }
  }
}

interface PublicVoice {
  voice_id: string
  name: string
  category: string
  labels: Record<string, string>
  preview_url: string
}

async function fetchPublicVoices(): Promise<PublicVoice[]> {
  const response = await fetchAPI(`${getBaseUrl()}/v1/voices`, { method: "GET" })
  const data: any = JSON.parse(response)
  if (data?.success === false) {
    throw new Error(data.error || "Failed to fetch public voices")
  }
  if (Array.isArray(data?.voices)) {
    return data.voices
  }
  if (Array.isArray(data?.data?.voices)) {
    return data.data.voices
  }
  return []
}

const logger = createLogger("elevenlabs")

export const ElevenlabsPlugin = async () => {
  const env = loadEnv("elevenlabs")

  const apiKey = env.ELEVENLABS_API_KEY
  const defaultVoiceId = env.ELEVENLABS_DEFAULT_VOICE_ID || "EXAVITQu4vr4xnSDxMaL" // Sarah
  const defaultModelId = env.ELEVENLABS_DEFAULT_MODEL_ID || "eleven_turbo_v2_5"
  const isConfigured = !!apiKey

  // Return limited toolset when not configured
  if (!isConfigured) {
    logger.warn("ELEVENLABS_API_KEY not set - returning limited toolset")
    return createPlugin([
      {
        name: "elevenlabs-test-connection",
        description: "Test ElevenLabs plugin configuration status",
        schema: z.object({}),
        async execute() {
          return JSON.stringify({
            success: false,
            status: "not_configured",
            message: "ElevenLabs plugin not configured. Please set ELEVENLABS_API_KEY environment variable.",
            help: "Get your API key from https://elevenlabs.io/ and add it to your .env file"
          }, null, 2)
        }
      },
      {
        name: "elevenlabs-play-voice-preview",
        description: "Search and play voice previews from ElevenLabs public voice library. No API key required.",
        schema: z.object({
          name: z.string().optional().describe("Filter by voice name"),
          accent: z.string().optional().describe("Filter by accent (e.g., 'british', 'american')"),
          gender: z.enum(["male", "female"]).optional().describe("Filter by gender"),
          limit: z.number().optional().default(5).describe("Maximum voices to return")
        }),
        async execute(args: any) {
          try {
            const voices = await fetchPublicVoices()
            let filtered = voices.filter((voice: PublicVoice) => {
              if (args.name && !voice.name.toLowerCase().includes(args.name.toLowerCase())) return false
              if (args.accent && voice.labels?.accent?.toLowerCase() !== args.accent.toLowerCase()) return false
              if (args.gender && voice.labels?.gender?.toLowerCase() !== args.gender.toLowerCase()) return false
              return true
            }).slice(0, args.limit || 5)

            return JSON.stringify({
              success: true,
              data: {
                totalFound: filtered.length,
                voices: filtered.map((v: PublicVoice) => ({
                  voiceId: v.voice_id,
                  name: v.name,
                  category: v.category,
                  accent: v.labels?.accent,
                  gender: v.labels?.gender,
                  previewUrl: v.preview_url
                }))
              },
              message: `Found ${filtered.length} voice(s). Set ELEVENLABS_API_KEY to use text-to-speech features.`
            }, null, 2)
          } catch (error: any) {
            return JSON.stringify({ success: false, error: error.message }, null, 2)
          }
        }
      }
    ])
  }

  const client = new ElevenLabsClient({ apiKey })

  const tools: ToolDefinition[] = [
    {
      name: "elevenlabs-test-connection",
      description: "Test ElevenLabs connection and configuration status",
      schema: z.object({}),
      async execute() {
        try {
          logger.info("Testing ElevenLabs connection")

          // Test basic API connectivity
          const userInfo = await client.user.get()

          return JSON.stringify({
            success: true,
            status: "connected",
            message: "ElevenLabs connection successful",
            details: {
              subscription: userInfo.subscription,
              defaultVoiceId,
              defaultModelId,
              voiceSamplesInfo: getVoiceSamplesInfo()
            }
          }, null, 2)
        } catch (error: any) {
          logger.error(`ElevenLabs connection test failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            status: "connection_failed",
            message: "Failed to connect to ElevenLabs API",
            error: error.message,
            details: {
              apiKeyConfigured: !!apiKey,
              defaultVoiceId,
              defaultModelId
            }
          }, null, 2)
        }
      }
    },
    {
      name: "generate-audio",
      description: `Generate natural-sounding speech from text using ElevenLabs text-to-speech. Supports v3 audio tags and multi-character dialogue.

MULTI-CHARACTER DIALOGUE FORMAT (requires eleven_v3 model):
Write dialogue with speaker names followed by colons, using audio tags for emotion:

Example:
Marissa: [starting to speak] So I was thinking we could—
Chris: [interrupting] —test our new timing features?
Marissa: [surprised] Exactly! How did you—
Chris: [overlapping] —know what you were thinking? Lucky guess!
Marissa: [laughs] Honestly? This is kind of fun.

COMMON AUDIO TAGS:
- Emotions: [excited], [annoyed], [flustered], [surprised], [panicking], [casual]
- Turn-taking: [interrupting], [overlapping], [cuts in], [interjecting]
- Delivery: [whispers], [sarcastic], [fast-paced], [hesitates], [drawn out]
- Actions: [laughs], [sighs], [gasps], [clears throat]
- Character voices: [childlike tone], [deep voice], [pirate voice], [robotic tone]
- Accents: [French accent], [British accent], [Southern accent]`,
      schema: z.object({
        text: z.string().describe("The text to convert to speech. For multi-character dialogue, use 'Speaker: [emotion] text' format. Use v3 audio tags like [whispers], [sarcastic], [interrupting], [laughs] for natural dialogue"),
        voiceId: z.string().optional().describe("Voice ID to use. Use play-voice-preview to find voices. Defaults to ELEVENLABS_DEFAULT_VOICE_ID env var or Sarah"),
        modelId: z.string().optional().describe("Model ID to use. Use 'eleven_v3' for multi-character dialogue and audio tags. Defaults to ELEVENLABS_DEFAULT_MODEL_ID env var or eleven_turbo_v2_5"),
        stability: z.number().min(0).max(1).optional().default(0.5).describe("Voice stability (0-1, higher = more stable, lower = more emotional range)"),
        similarityBoost: z.number().min(0).max(1).optional().default(0.75).describe("Similarity boost (0-1, higher = more similar to original voice)"),
        style: z.number().min(0).max(1).optional().default(0).describe("Style exaggeration (0-1, higher = more pronounced style, consumes more resources)"),
        useSpeakerBoost: z.boolean().optional().default(true).describe("Boost similarity to original speaker (increases latency)"),
        outputPath: z.string().optional().describe("Optional path to save the audio file (e.g., 'output.mp3')"),
        outputFormat: z.string().optional().default("mp3_44100_128").describe("Audio output format (e.g., 'mp3_44100_128', 'mp3_22050_96', 'pcm_16000')"),
        playAudio: z.boolean().optional().default(false).describe("Play the generated audio automatically after generation (uses system default audio player)")
      }),
      execute: async (args) => {
        try {
          const voiceId = args.voiceId || defaultVoiceId

          // Detect if using v3 audio tags or multi-character dialogue
          const hasAudioTags = /\[.*?\]/.test(args.text)
          const hasMultiCharacter = /^[A-Z][a-zA-Z]*:\s/m.test(args.text) // Detects "Speaker: " format
          const needsV3 = hasAudioTags || hasMultiCharacter

          // Auto-switch to eleven_v3 for multi-character dialogue or audio tags
          const modelId = args.modelId || (needsV3 ? "eleven_v3" : defaultModelId)

          if (needsV3 && !modelId.includes('eleven_v3')) {
            logger.warn("Multi-character dialogue or audio tags detected. Switching to eleven_v3 model for best results.")
          }

          const logPrefix = hasMultiCharacter ? '(multi-character) ' : (hasAudioTags ? '(with audio tags) ' : '')
          logger.info(`${logPrefix}Generating audio for text: "${args.text.substring(0, 50)}..."`)

          const audioStream = await client.generate({
            voice: voiceId,
            text: args.text,
            model_id: modelId,
            output_format: args.outputFormat,
            voice_settings: {
              stability: args.stability,
              similarity_boost: args.similarityBoost,
              style: args.style,
              use_speaker_boost: args.useSpeakerBoost
            }
          })

          const chunks: Buffer[] = []
          for await (const chunk of audioStream) {
            chunks.push(chunk)
          }

          const audioBuffer = Buffer.concat(chunks)

          let savedPath: string | undefined
          let played = false

          if (args.outputPath) {
            const fullPath = path.resolve(args.outputPath)
            await fs.writeFile(fullPath, audioBuffer)
            savedPath = fullPath
            logger.info(`Audio saved to: ${fullPath}`)
          }

          if (args.playAudio) {
            const audioPlayStream = Readable.from(audioBuffer)
            await play(audioPlayStream)
            played = true
            logger.info(`Audio played directly using ElevenLabs SDK`)
          }

          // Extract speaker names from multi-character dialogue
          const speakers = hasMultiCharacter 
            ? [...new Set(args.text.match(/^([A-Z][a-zA-Z]*):/gm)?.map((s: string) => s.replace(':', '')) || [])]
            : []

          return JSON.stringify({
            success: true,
            data: {
              textLength: args.text.length,
              audioSize: audioBuffer.length,
              voiceId,
              modelId,
              outputFormat: args.outputFormat,
              savedPath,
              played,
              settings: {
                stability: args.stability,
                similarityBoost: args.similarityBoost,
                style: args.style,
                useSpeakerBoost: args.useSpeakerBoost
              },
              multiCharacterDialogue: hasMultiCharacter,
              speakers: speakers.length > 0 ? speakers : undefined,
              audioTagsDetected: hasAudioTags
            },
            message: savedPath
              ? `Audio generated and saved to ${savedPath}${played ? ' (and played)' : ''}`
              : played 
                ? `Audio generated and played successfully${hasMultiCharacter ? ` with ${speakers.length} character(s): ${speakers.join(', ')}` : ''}`
                : "Audio generated successfully (use outputPath to save or playAudio to play)"
          }, null, 2)
        } catch (error: any) {
          logger.error(`Generate audio failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
    },
    {
      name: "list-voices",
      description: "List all available voices from ElevenLabs",
      schema: z.object({
        showDetails: z.boolean().optional().default(false).describe("Include detailed voice information")
      }),
      execute: async (args) => {
        try {
          logger.info("Fetching available voices")

          const response = await client.voices.getAll()

          const voices = response.voices.map(voice => ({
            id: voice.voice_id,
            name: voice.name,
            category: voice.category,
            description: voice.description,
            labels: voice.labels,
            previewUrl: voice.preview_url,
            ...(args.showDetails && {
              settings: voice.settings,
              samples: voice.samples
            })
          }))

          return JSON.stringify({
            success: true,
            data: {
              totalVoices: voices.length,
              voices
            },
            message: `Found ${voices.length} available voices`
          }, null, 2)
        } catch (error: any) {
          logger.error(`List voices failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
    },
    {
      name: "get-voice",
      description: "Get detailed information about a specific voice",
      schema: z.object({
        voiceId: z.string().describe("The ID of the voice to retrieve"),
        withSettings: z.boolean().optional().default(true).describe("Include voice settings in response")
      }),
      execute: async (args) => {
        try {
          logger.info(`Getting voice details for ID: ${args.voiceId}`)

          const voice = await client.voices.get(args.voiceId, {
            with_settings: args.withSettings
          })

          return JSON.stringify({
            success: true,
            data: {
              id: voice.voice_id,
              name: voice.name,
              category: voice.category,
              description: voice.description,
              labels: voice.labels,
              previewUrl: voice.preview_url,
              settings: voice.settings,
              samples: voice.samples
            }
          }, null, 2)
        } catch (error: any) {
          logger.error(`Get voice failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
         }
       }
     },
    {
      name: "get-models",
      description: "Get all available models from ElevenLabs",
      schema: z.object({}),
      execute: async () => {
        try {
          logger.info("Fetching available models")

          const models = await client.models.getAll()

          return JSON.stringify({
            success: true,
            data: {
              totalModels: models.length,
              models: models.map(model => ({
                id: model.model_id,
                name: model.name,
                description: model.description,
                canDoTextToSpeech: model.can_do_text_to_speech,
                canDoVoiceConversion: model.can_do_voice_conversion,
                languages: model.languages
              }))
            },
            message: `Found ${models.length} available models`
          }, null, 2)
        } catch (error: any) {
          logger.error(`Get models failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
    },
    {
      name: "get-user-info",
      description: "Get information about the current user and their subscription",
      schema: z.object({}),
      execute: async () => {
        try {
          logger.info("Fetching user information")

          const userInfo = await client.user.get()

          return JSON.stringify({
            success: true,
            data: {
              subscription: userInfo.subscription,
              // Note: User info properties may vary - returning basic info
              // Available properties depend on user subscription level
            }
          }, null, 2)
        } catch (error: any) {
          logger.error(`Get user info failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
     },
    {
      name: "elevenlabs-get-user-info",
      description: "Get information about the current user and their subscription",
      schema: z.object({}),
      execute: async () => {
        try {
          logger.info("Fetching user information")

          const userInfo = await client.user.get()

          return JSON.stringify({
            success: true,
            data: {
              subscription: userInfo.subscription,
              // Note: User info properties may vary - returning basic info
              // Available properties depend on user subscription level
            }
          }, null, 2)
        } catch (error: any) {
          logger.error(`Get user info failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
     },
    {
      name: "get-history",
      description: "Get history of generated audio items",
      schema: z.object({
        pageSize: z.number().optional().default(10).describe("Number of items per page")
      }),
      execute: async (args) => {
        try {
          logger.info("Fetching generation history")

          const history = await client.history.getAll({
            page_size: args.pageSize
          })

          return JSON.stringify({
            success: true,
            data: {
              totalItems: history.history.length,
              hasMore: history.has_more,
              items: history.history.map(item => ({
                id: item.history_item_id,
                text: item.text,
                voiceId: item.voice_id,
                voiceName: item.voice_name,
                modelId: item.model_id,
                dateUnix: item.date_unix,
                characterCountChangeFrom: item.character_count_change_from,
                characterCountChangeTo: item.character_count_change_to,
                state: item.state
              }))
            }
          }, null, 2)
        } catch (error: any) {
          logger.error(`Get history failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
    },
    {
      name: "design-voice",
      description: "Design and generate a new synthetic voice from a text description. Creates voice previews that can be saved to your library.",
      schema: z.object({
        voiceDescription: z.string().describe("Description of the voice to create (e.g., 'A warm, friendly female voice with a slight British accent, suitable for audiobooks')"),
        text: z.string().describe("Sample text that the generated voice will speak for preview"),
        loudness: z.number().min(-1).max(1).optional().describe("Loudness adjustment (-1 to 1, default 0)"),
        quality: z.number().min(0).max(1).optional().describe("Quality level (0-1, higher = better quality but slower)"),
        seed: z.number().optional().describe("Random seed for reproducible voice generation"),
        outputPath: z.string().optional().describe("Optional path to save the preview audio (e.g., 'voice_preview.mp3')")
      }),
      execute: async (args) => {
        try {
          logger.info(`Designing voice: "${args.voiceDescription.substring(0, 50)}..."`)

          const response = await client.textToVoice.createPreviews({
            voice_description: args.voiceDescription,
            text: args.text,
            ...(args.loudness !== undefined && { loudness: args.loudness }),
            ...(args.quality !== undefined && { quality: args.quality }),
            ...(args.seed !== undefined && { seed: args.seed })
          })

          const previews = response.previews || []

          if (previews.length === 0) {
            return JSON.stringify({
              success: false,
              error: "No voice previews were generated. Try adjusting your description."
            }, null, 2)
          }

          // Save first preview if output path specified
          let savedPath: string | undefined
          if (args.outputPath && previews[0]?.audio_base_64) {
            const audioBuffer = Buffer.from(previews[0].audio_base_64, 'base64')
            const fullPath = path.resolve(args.outputPath)
            await fs.writeFile(fullPath, audioBuffer)
            savedPath = fullPath
            logger.info(`Voice preview saved to: ${fullPath}`)
          }

          return JSON.stringify({
            success: true,
            data: {
              totalPreviews: previews.length,
              previews: previews.map((preview: any, index: number) => ({
                index,
                generatedVoiceId: preview.generated_voice_id,
                hasAudio: !!preview.audio_base_64,
                audioSizeBytes: preview.audio_base_64 ? Buffer.from(preview.audio_base_64, 'base64').length : 0
              })),
              savedPath,
              voiceDescription: args.voiceDescription,
              sampleText: args.text
            },
            message: savedPath 
              ? `Generated ${previews.length} voice preview(s). First preview saved to ${savedPath}. Use the generated_voice_id with create-voice-from-preview to save to your library.`
              : `Generated ${previews.length} voice preview(s). Use the generated_voice_id with create-voice-from-preview to save to your library.`
          }, null, 2)
        } catch (error: any) {
          logger.error(`Design voice failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
    },
    {
      name: "create-voice-from-preview",
      description: "Save a designed voice preview to your ElevenLabs voice library. Use after design-voice to permanently save a voice you like.",
      schema: z.object({
        generatedVoiceId: z.string().describe("The generated_voice_id from design-voice response"),
        voiceName: z.string().describe("Name to give the new voice in your library"),
        voiceDescription: z.string().describe("The original voice description used to generate the preview"),
        labels: z.string().optional().describe("JSON string of labels (e.g., '{\"accent\": \"british\", \"gender\": \"female\"}')")
      }),
      execute: async (args) => {
        try {
          logger.info(`Creating voice from preview: ${args.voiceName}`)

          let parsedLabels: Record<string, string> | undefined
          if (args.labels) {
            try {
              parsedLabels = JSON.parse(args.labels)
            } catch {
              return JSON.stringify({
                success: false,
                error: "Invalid labels JSON format. Expected format: '{\"key\": \"value\"}'"
              }, null, 2)
            }
          }

          const response = await client.textToVoice.createVoiceFromPreview({
            voice_name: args.voiceName,
            voice_description: args.voiceDescription,
            generated_voice_id: args.generatedVoiceId,
            ...(parsedLabels && { labels: parsedLabels })
          })

          return JSON.stringify({
            success: true,
            data: {
              voiceId: response.voice_id,
              voiceName: args.voiceName,
              voiceDescription: args.voiceDescription
            },
            message: `Voice "${args.voiceName}" created successfully with ID: ${response.voice_id}. You can now use this voice_id with generate-audio.`
          }, null, 2)
        } catch (error: any) {
          logger.error(`Create voice from preview failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
    },
    {
      name: "play-voice-preview",
      description: "Search and play voice previews from ElevenLabs public voice library. No API key required. Filters by name, accent, gender, age, or use case.",
      schema: z.object({
        name: z.string().optional().describe("Filter by voice name (e.g., 'Brian', 'Sarah')"),
        accent: z.string().optional().describe("Filter by accent (e.g., 'british', 'american', 'australian')"),
        gender: z.enum(["male", "female"]).optional().describe("Filter by gender"),
        age: z.enum(["young", "middle aged", "old"]).optional().describe("Filter by age category"),
        useCase: z.string().optional().describe("Filter by use case (e.g., 'narration', 'conversational', 'news')"),
        play: z.boolean().optional().default(true).describe("Automatically play the preview audio"),
        limit: z.number().optional().default(5).describe("Maximum number of voices to return")
      }),
      execute: async (args) => {
        try {
          logger.info("Fetching public voices for preview")

          const voices = await fetchPublicVoices()

          let filtered = voices.filter(voice => {
            if (args.name && !voice.name.toLowerCase().includes(args.name.toLowerCase())) {
              return false
            }
            if (args.accent && voice.labels?.accent?.toLowerCase() !== args.accent.toLowerCase()) {
              return false
            }
            if (args.gender && voice.labels?.gender?.toLowerCase() !== args.gender.toLowerCase()) {
              return false
            }
            if (args.age && voice.labels?.age?.toLowerCase() !== args.age.toLowerCase()) {
              return false
            }
            if (args.useCase && voice.labels?.use_case?.toLowerCase() !== args.useCase.toLowerCase()) {
              return false
            }
            return true
          })

          filtered = filtered.slice(0, args.limit)

          if (filtered.length === 0) {
            return JSON.stringify({
              success: false,
              error: "No voices found matching the filters",
              availableFilters: {
                accents: [...new Set(voices.map(v => v.labels?.accent).filter(Boolean))],
                genders: [...new Set(voices.map(v => v.labels?.gender).filter(Boolean))],
                ages: [...new Set(voices.map(v => v.labels?.age).filter(Boolean))],
                useCases: [...new Set(voices.map(v => v.labels?.use_case).filter(Boolean))]
              }
            }, null, 2)
          }

          const results = filtered.map(voice => ({
            voiceId: voice.voice_id,
            name: voice.name,
            category: voice.category,
            accent: voice.labels?.accent,
            gender: voice.labels?.gender,
            age: voice.labels?.age,
            useCase: voice.labels?.use_case,
            previewUrl: voice.preview_url
          }))

          let playbackStatus: string | null = null
          if (args.play && filtered.length > 0 && filtered[0].preview_url) {
            const previewUrl = filtered[0].preview_url

            try {
              const response = await fetch(previewUrl)
              const audioBuffer = Buffer.from(await response.arrayBuffer())

              // Use ElevenLabs built-in play function
              const audioStream = Readable.from(audioBuffer)
              await play(audioStream)

              logger.info(`Playing preview for voice: ${filtered[0].name}`)
              playbackStatus = "playing"
            } catch (err: any) {
              playbackStatus = `Playback failed: ${err.message}`
              logger.warn(playbackStatus)
            }
          }

          return JSON.stringify({
            success: true,
            data: {
              totalFound: results.length,
              voices: results,
              playbackStatus
            },
            message: playbackStatus === "playing"
              ? `Playing preview for ${results[0]?.name}. Found ${results.length} matching voice(s).`
              : playbackStatus
                ? `Found ${results.length} matching voice(s). ${playbackStatus}`
                : `Found ${results.length} matching voice(s).`
          }, null, 2)
        } catch (error: any) {
          logger.error(`Play voice preview failed: ${error.message}`)
          return JSON.stringify({
            success: false,
            error: error.message
          }, null, 2)
        }
      }
    }
  ]

  // Add conversation tools (Text to Dialogue API)
  tools.push(...createConversationTools(client, apiKey))

  // Add script production tool
  tools.push(createScriptProductionTool(client, apiKey))

  // Add audio tags helper tool
  tools.push(createAudioTagsHelperTool())

  // Conditionally add voice cloning tools if voice-samples folder exists
  const voiceSamplesInfo = getVoiceSamplesInfo()
  if (voiceSamplesInfo.exists) {
    logger.info(`Voice cloning enabled: ${voiceSamplesInfo.files.length} sample(s) found in voice-samples/`)
    tools.push(...createVoiceCloningTools(client))
  } else {
    logger.debug("Voice cloning tools not loaded: no voice-samples directory or audio files found")
  }

  // Add OpenAPI-generated tools (filtered to avoid duplicates with manual tools)
  // Manual tools that have OpenAPI equivalents (kept manual for better SDK integration):
  // - generate-audio → elevenlabs-text-to-speech-full (manual has streaming/playback)
  // - list-voices → elevenlabs-get-voices (manual has better formatting)
  // - get-voice → elevenlabs-get-voice-by-id
  // - get-models → elevenlabs-get-models
  // - get-user-info → elevenlabs-get-user-info
  // - get-history → elevenlabs-get-speech-history
  // - design-voice → elevenlabs-text-to-voice (manual has preview saving)
  // - create-voice-from-preview → elevenlabs-create-voice
  // - play-voice-preview → elevenlabs-get-library-voices (manual has audio playback)
  const manualToolNames = new Set(tools.map(t => t.name))
  const duplicateOpenAPITools = new Set([
    'elevenlabs-text-to-speech-full',
    'elevenlabs-text-to-speech-stream',
    'elevenlabs-get-voices',
    'elevenlabs-get-voice-by-id',
    'elevenlabs-get-models',
    'elevenlabs-get-user-subscription-info',
    'elevenlabs-get-speech-history',
    'elevenlabs-text-to-voice',
    'elevenlabs-create-voice',
    'elevenlabs-get-library-voices',
    'elevenlabs-generate-random-voice'
  ])

  const filteredOpenAPITools = openAPITools.filter(tool => 
    !manualToolNames.has(tool.name) && !duplicateOpenAPITools.has(tool.name)
  )

  logger.info(`Adding ${filteredOpenAPITools.length} OpenAPI tools (${openAPITools.length - filteredOpenAPITools.length} duplicates filtered)`)
  tools.push(...filteredOpenAPITools)

  return createPlugin(tools)
}
